use rk3588_boot_support::{BarrierOps,ByteTransfer,DelayUs,MemoryTransfer,Mmio32};
use crate::stage12::{pmumcu_start,PmuMcuError};
pub const PMUMCU_SLEEP_TAG_DST:u64=0xFF00_0C00;pub const PMUMCU_SLEEP_TAG_MAGIC:u32=0x526B_0001;pub const PMUMCU_SLEEP_TAG_MAX:u32=0x400;pub const PMUMCU_DEFAULT_TAG_BYTES:u32=104;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum WakeTagSource{External{src:u64,magic:u32,bytes:u32},Default{src:u64}}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum PmuMcuWakeError{TagsTooLarge,Start(PmuMcuError)}
pub fn prepare_pmumcu_wakeup<I:Mmio32+DelayUs+BarrierOps+ByteTransfer>(io:&mut I,tags:WakeTagSource,entry:u32)->Result<u32,PmuMcuWakeError>{let(src,bytes)=match tags{WakeTagSource::External{src,magic,bytes} if magic==PMUMCU_SLEEP_TAG_MAGIC=>{if bytes>PMUMCU_SLEEP_TAG_MAX{return Err(PmuMcuWakeError::TagsTooLarge)}(src,bytes)},WakeTagSource::External{src,..}|WakeTagSource::Default{src}=>(src,PMUMCU_DEFAULT_TAG_BYTES)};io.copy_bytes_exact(PMUMCU_SLEEP_TAG_DST,src,bytes);pmumcu_start(io,entry).map_err(PmuMcuWakeError::Start)?;Ok(bytes)}
pub fn restore_and_start_pmumcu<I:Mmio32+DelayUs+BarrierOps+MemoryTransfer>(io:&mut I,enabled:bool,saved:bool,entry:u32)->Result<bool,PmuMcuError>{let restored=crate::stage13::restore_pmumcu_image(io,enabled,saved);if restored{pmumcu_start(io,entry)?}Ok(restored)}
#[cfg(test)]mod tests{use super::*;struct M{copied:(u64,u64,u32),status:u32}impl Mmio32 for M{fn read32(&mut self,a:u64)->u32{match a{0xFD7F0A00=>0x2000,0xFD8D4010=>self.status,_=>0}}fn write32(&mut self,_:u64,_:u32){}}impl DelayUs for M{fn delay_us(&mut self,_:u32){}}impl BarrierOps for M{fn dsb(&mut self){}fn isb(&mut self){}}impl ByteTransfer for M{fn copy_bytes_exact(&mut self,d:u64,s:u64,b:u32){self.copied=(d,s,b)}}impl MemoryTransfer for M{fn copy_words_exact(&mut self,_:u64,_:u64,_:u32){}}#[test]fn tags(){let mut m=M{copied:(0,0,0),status:0};assert_eq!(prepare_pmumcu_wakeup(&mut m,WakeTagSource::External{src:0x1000,magic:PMUMCU_SLEEP_TAG_MAGIC,bytes:64},0xFF080000),Ok(64));assert_eq!(m.copied,(PMUMCU_SLEEP_TAG_DST,0x1000,64));assert_eq!(prepare_pmumcu_wakeup(&mut m,WakeTagSource::External{src:0,magic:PMUMCU_SLEEP_TAG_MAGIC,bytes:0x401},0),Err(PmuMcuWakeError::TagsTooLarge));}}
